class Solution { public:
 int countPairs(vector<int>& nums){int ans=0;for(int i=0;i<(int)nums.size();++i)for(int j=0;j<i;++j){string a=to_string(nums[i]),b=to_string(nums[j]);int m=max(a.size(),b.size());a=string(m-a.size(),'0')+a;b=string(m-b.size(),'0')+b;vector<int>diff;for(int p=0;p<m;++p)if(a[p]!=b[p])diff.push_back(p);if(diff.empty() || (diff.size()==2&&a[diff[0]]==b[diff[1]]&&a[diff[1]]==b[diff[0]]))++ans;}return ans;}
};
